for(int k = 0; k < n; k++)      // k = the allowed stop-over
  for(int i = 0; i < n; i++)
    for(int j = 0; j < n; j++)
      if(d[i][k] != INF && d[k][j] != INF &&
         d[i][k] + d[k][j] < d[i][j])
          d[i][j] = d[i][k] + d[k][j];

